"""Fixed catalog-only B PRECOPY schema observation; no business rows."""
import hashlib,json
from pathlib import Path
CATALOG=Path(__file__).resolve().parents[1]/'manifests/b-data-writer-handoff-r1.json'
def digest(raw):return hashlib.sha256(raw).hexdigest()

def catalog_sql():
    catalog = CATALOG.read_bytes()
    assert digest(catalog) == '8e5d57c4c45af3402da6328289ba511aa9a9fad9cafe109249d31d9cf7f27877'
    names = json.loads(catalog)['tables']
    values = ','.join("('%s')" % n for n in names)
    selected = "WITH selected(name) AS (VALUES " + values + "), rel AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN selected s ON s.name=c.relname WHERE n.nspname='public') "
    queries = [
        "SELECT json_build_object('kind','database_meta','encoding',pg_encoding_to_char(encoding),'collate',datcollate,'ctype',datctype,'owner',pg_get_userbyid(datdba)) FROM pg_database WHERE datname=current_database();",
        selected + "SELECT json_build_object('kind','column_meta','table',c.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'type_schema',tn.nspname,'type_kind',t.typtype,'not_null',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'collation',co.collname,'default_sha256',CASE WHEN d.oid IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(d.adbin,d.adrelid),'UTF8')),'hex') END) FROM rel c JOIN pg_attribute a ON a.attrelid=c.oid JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace tn ON tn.oid=t.typnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum;",
        selected + "SELECT json_build_object('kind','constraint_meta','table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred,'target_schema',rn.nspname,'target',r.relname,'definition_sha256',encode(sha256(convert_to(pg_get_constraintdef(k.oid),'UTF8')),'hex')) FROM rel c JOIN pg_constraint k ON k.conrelid=c.oid LEFT JOIN pg_class r ON r.oid=k.confrelid LEFT JOIN pg_namespace rn ON rn.oid=r.relnamespace ORDER BY c.relname,k.conname;",
        selected + "SELECT json_build_object('kind','index_meta','table',c.relname,'name',ic.relname,'valid',i.indisvalid,'ready',i.indisready,'definition_sha256',encode(sha256(convert_to(pg_get_indexdef(i.indexrelid),'UTF8')),'hex')) FROM rel c JOIN pg_index i ON i.indrelid=c.oid JOIN pg_class ic ON ic.oid=i.indexrelid ORDER BY c.relname,ic.relname;",
        selected + "SELECT json_build_object('kind','trigger_meta','table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function_schema',n.nspname,'function',p.proname,'definition_sha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex')) FROM rel c JOIN pg_trigger t ON t.tgrelid=c.oid JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace n ON n.oid=p.pronamespace WHERE NOT t.tgisinternal ORDER BY c.relname,t.tgname;",
        selected + "SELECT DISTINCT jsonb_build_object('kind','function_meta','schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'language',l.lanname,'security_definer',p.prosecdef,'settings_count',coalesce(cardinality(p.proconfig),0),'exact_pg_catalog_path',p.proconfig=ARRAY['search_path=pg_catalog']::text[],'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) FROM rel c JOIN pg_trigger t ON t.tgrelid=c.oid JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE NOT t.tgisinternal;",
        selected + "SELECT json_build_object('kind','relation_meta','table',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'kind_code',c.relkind,'persistence',c.relpersistence,'partition',c.relispartition,'replica_identity',c.relreplident,'total_bytes',pg_total_relation_size(c.oid)) FROM rel c ORDER BY c.relname;",
        selected + "SELECT json_build_object('kind','incoming_fk_meta','from_schema',n.nspname,'from_table',c.relname,'name',k.conname,'to_table',r.relname,'definition_sha256',encode(sha256(convert_to(pg_get_constraintdef(k.oid),'UTF8')),'hex')) FROM rel r JOIN pg_constraint k ON k.confrelid=r.oid JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE k.contype='f' AND k.conrelid NOT IN(SELECT oid FROM rel) ORDER BY n.nspname,c.relname,k.conname;",
        selected + "SELECT json_build_object('kind','attached_extension_meta','object',pg_describe_object(d.classid,d.objid,d.objsubid),'extension',e.extname,'version',e.extversion) FROM rel c JOIN pg_depend d ON d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e' JOIN pg_extension e ON e.oid=d.refobjid;",
        "SELECT json_build_object('kind','safe_setting_meta','name',name,'value',setting,'source',source) FROM pg_settings WHERE name IN('shared_preload_libraries','session_preload_libraries','local_preload_libraries','jit','dynamic_library_path') ORDER BY name;",
        selected + "SELECT json_build_object('kind','owner_role_meta','name',r.rolname,'superuser',r.rolsuper,'login',r.rolcanlogin,'bypass_rls',r.rolbypassrls,'create_role',r.rolcreaterole) FROM pg_roles r WHERE r.oid IN(SELECT relowner FROM rel UNION SELECT datdba FROM pg_database WHERE datname=current_database() UNION SELECT p.proowner FROM rel c JOIN pg_trigger t ON t.tgrelid=c.oid JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal) ORDER BY r.rolname;",
    ]
    return ('\n'.join(queries)+'\n').encode()

